static int recreate_image(void){if(image>0)dm_host_image_free(image);image=dm_host_image_create(PAINT_W,PAINT_H,pixels);return image>0;}
static int resize_canvas(int width,int height){width=clamp_i(width,1,MAX_PAINT_W);height=clamp_i(height,1,MAX_PAINT_H);if(width==PAINT_W&&height==PAINT_H)return 1;int old_w=PAINT_W,old_h=PAINT_H,old_count=PAINT_PIXELS;if(!ensure_buffers(max_i(old_count,width*height))){set_status("Memoria insufficiente per ampliare la tela");return 0;}for(int i=0;i<old_count;i++)undo[i]=pixels[i];canvas_w=width;canvas_h=height;uint32_t bg=background();for(int i=0;i<PAINT_PIXELS;i++)pixels[i]=bg;for(int y=0;y<old_h&&y<height;y++)for(int x=0;x<old_w&&x<width;x++)pixels[y*width+x]=undo[y*old_w+x];has_undo=0;selection_active=paste_mode=0;offset_x=offset_y=0;fit_mode=0;zoom_percent=100;dirty=1;if(!recreate_image()){set_status("Memoria insufficiente per la tela");return 0;}dm_host_image_update(image,pixels);return 1;}
