static void set_pixel(int x,int y,uint32_t c){if(x>=0&&x<PAINT_W&&y>=0&&y<PAINT_H)pixels[y*PAINT_W+x]=c;}
static void save_undo(void){for(int i=0;i<PAINT_PIXELS;i++)undo[i]=pixels[i];has_undo=1;}
static void changed(void){dirty=1;if(image>0)dm_host_image_update(image,pixels);}
static uint32_t foreground(void){return fg_custom_active?fg_custom:palette[fg_index];}
static uint32_t background(void){return palette[bg_index];}
static void dot(int x,int y){int radius=(brush_size-1)/2;uint32_t c=(tool==TOOL_ERASER||eraser_mode)?background():foreground();for(int dy=-radius;dy<=radius;dy++)for(int dx=-radius;dx<=radius;dx++)if(dx*dx+dy*dy<=radius*radius+1)set_pixel(x+dx,y+dy,c);}
static void line_pixels(int x0,int y0,int x1,int y1){int dx=x1>x0?x1-x0:x0-x1,sx=x0<x1?1:-1,dy=y1>y0?y0-y1:y1-y0,sy=y0<y1?1:-1,err=dx+dy;for(;;){dot(x0,y0);if(x0==x1&&y0==y1)break;int e2=2*err;if(e2>=dy){err+=dy;x0+=sx;}if(e2<=dx){err+=dx;y0+=sy;}}}
static void draw_rect(int x0,int y0,int x1,int y1,int rounded){int l=min_i(x0,x1),r=max_i(x0,x1),t=min_i(y0,y1),b=max_i(y0,y1);if(fill_style==1){for(int y=t;y<=b;y++)for(int x=l;x<=r;x++){if(!rounded||(x>=l+3&&x<=r-3)||(y>=t+3&&y<=b-3))set_pixel(x,y,foreground());}}else if(fill_style==2){for(int y=t;y<=b;y++)for(int x=l;x<=r;x++)if(((x+y)&3)<2)set_pixel(x,y,foreground());}else{line_pixels(l,t,r,t);line_pixels(r,t,r,b);line_pixels(r,b,l,b);line_pixels(l,b,l,t);}if(rounded&&fill_style==0){set_pixel(l,t,background());set_pixel(l+1,t,background());set_pixel(r,t,background());set_pixel(r-1,t,background());set_pixel(l,b,background());set_pixel(l+1,b,background());set_pixel(r,b,background());set_pixel(r-1,b,background());}}
static void draw_ellipse(int x0,int y0,int x1,int y1){int l=min_i(x0,x1),r=max_i(x0,x1),t=min_i(y0,y1),b=max_i(y0,y1),rx=max_i(1,(r-l)/2),ry=max_i(1,(b-t)/2),cx=(l+r)/2,cy=(t+b)/2;int64_t edge=(int64_t)rx*rx*ry*ry;for(int y=t;y<=b;y++)for(int x=l;x<=r;x++){int64_t dx=x-cx,dy=y-cy,q=dx*dx*ry*ry+dy*dy*rx*rx;if((fill_style==1&&q<=edge)||(fill_style==2&&q<=edge&&q>edge-edge/5)||(fill_style==0&&q<=edge&&q>edge-edge/ry))set_pixel(x,y,foreground());}}
static void draw_airbrush(int cx,int cy){for(int i=0;i<30;i++){random_seed=random_seed*1664525u+1013904223u;int dx=(int)(random_seed%17)-8;random_seed=random_seed*1664525u+1013904223u;int dy=(int)(random_seed%17)-8;if(dx*dx+dy*dy<=64)set_pixel(cx+dx,cy+dy,foreground());}}
static void fill_area(int sx,int sy){uint32_t target=pixels[sy*PAINT_W+sx],replacement=foreground();if(target==replacement)return;unsigned head=0,tail=0;fill_queue[tail++]=(uint32_t)(sy*PAINT_W+sx);pixels[sy*PAINT_W+sx]=replacement;while(head<tail){uint32_t p=fill_queue[head++];int x=(int)(p%PAINT_W),y=(int)(p/PAINT_W);if(x>0&&pixels[p-1]==target){pixels[p-1]=replacement;fill_queue[tail++]=p-1;}if(x+1<PAINT_W&&pixels[p+1]==target){pixels[p+1]=replacement;fill_queue[tail++]=p+1;}if(y>0&&pixels[p-PAINT_W]==target){pixels[p-PAINT_W]=replacement;fill_queue[tail++]=p-PAINT_W;}if(y+1<PAINT_H&&pixels[p+PAINT_W]==target){pixels[p+PAINT_W]=replacement;fill_queue[tail++]=p+PAINT_W;}}changed();}
static int font_index(char c){if(c>='a'&&c<='z')c=(char)(c-'a'+'A');if(c>='A'&&c<='Z')return c-'A';if(c>='0'&&c<='9')return 26+c-'0';if(c=='.')return 36;if(c=='-')return 37;return -1;}
static void draw_text_pixels(int x,int y,const char*text){int cursor=x,line=x;for(int i=0;text[i];i++){if(text[i]=='\n'||cursor+6*text_scale>PAINT_W){cursor=line;y+=8*text_scale;if(text[i]=='\n')continue;}if(y+7*text_scale>PAINT_H)break;int gi=font_index(text[i]);if(gi>=0){for(int yy=0;yy<7;yy++)for(int xx=0;xx<5;xx++)if(font5x7[gi][yy]&(1u<<(4-xx)))for(int sy=0;sy<text_scale;sy++)for(int sx=0;sx<text_scale;sx++)set_pixel(cursor+xx*text_scale+sx,y+yy*text_scale+sy,foreground());}cursor+=6*text_scale;}changed();}
static void draw_polygon(void){if(polygon_count<2)return;for(int i=1;i<polygon_count;i++)line_pixels(polygon_x[i-1],polygon_y[i-1],polygon_x[i],polygon_y[i]);line_pixels(polygon_x[polygon_count-1],polygon_y[polygon_count-1],polygon_x[0],polygon_y[0]);changed();polygon_count=0;}
static void selection_copy(int cut){if(selection_active){clipboard_w=selection_x1-selection_x0+1;clipboard_h=selection_y1-selection_y0+1;}else{selection_x0=selection_y0=0;selection_x1=PAINT_W-1;selection_y1=PAINT_H-1;clipboard_w=PAINT_W;clipboard_h=PAINT_H;}if(clipboard_w<1||clipboard_h<1)return;for(int y=0;y<clipboard_h;y++)for(int x=0;x<clipboard_w;x++){int at=y*clipboard_w+x;selection_clipboard[at]=pixels[(selection_y0+y)*PAINT_W+selection_x0+x];if(cut)pixels[(selection_y0+y)*PAINT_W+selection_x0+x]=background();}if(cut){changed();selection_active=0;}paste_mode=0;}
static void paste_at(int x,int y){if(!clipboard_w||!clipboard_h)return;save_undo();for(int py=0;py<clipboard_h;py++)for(int px=0;px<clipboard_w;px++)if(x+px<PAINT_W&&y+py<PAINT_H)set_pixel(x+px,y+py,selection_clipboard[py*clipboard_w+px]);selection_x0=x;selection_y0=y;selection_x1=min_i(PAINT_W-1,x+clipboard_w-1);selection_y1=min_i(PAINT_H-1,y+clipboard_h-1);selection_active=1;paste_mode=0;changed();}
static void apply_shape(void){if(tool==TOOL_LINE)line_pixels(start_x,start_y,last_x,last_y);else if(tool==TOOL_RECT)draw_rect(start_x,start_y,last_x,last_y,0);else if(tool==TOOL_ROUNDRECT)draw_rect(start_x,start_y,last_x,last_y,1);else if(tool==TOOL_ELLIPSE)draw_ellipse(start_x,start_y,last_x,last_y);if(tool==TOOL_LINE||tool==TOOL_RECT||tool==TOOL_ROUNDRECT||tool==TOOL_ELLIPSE)changed();}
static void draw_ui_line(int x0,int y0,int x1,int y1,uint32_t color){int dx=x1>x0?x1-x0:x0-x1,sx=x0<x1?1:-1,dy=y1>y0?y0-y1:y1-y0,sy=y0<y1?1:-1,err=dx+dy;for(;;){dm_host_rect(x0,y0,1,1,color);if(x0==x1&&y0==y1)break;int e=2*err;if(e>=dy){err+=dy;x0+=sx;}if(e<=dx){err+=dx;y0+=sy;}}}
