static void layout(int width,int height){canvas_x=54;canvas_y=4;view_w=width-canvas_x-10;view_h=height-canvas_y-28;if(view_w<1)view_w=1;if(view_h<1)view_h=1;int scale=100;if(fit_mode){int sx=view_w*100/PAINT_W,sy=view_h*100/PAINT_H;scale=sx<sy?sx:sy;if(scale>100)scale=100;if(scale<10)scale=10;}else scale=zoom_percent;draw_w=PAINT_W*scale/100;draw_h=PAINT_H*scale/100;hbar=vbar=0;for(int i=0;i<3;i++){int aw=width-canvas_x-10-(vbar?12:0),ah=height-canvas_y-28-(hbar?12:0);if(aw<1)aw=1;if(ah<1)ah=1;view_w=aw;view_h=ah;hbar=draw_w>view_w;vbar=draw_h>view_h;}offset_x=clamp_i(offset_x,0,max_i(0,draw_w-view_w));offset_y=clamp_i(offset_y,0,max_i(0,draw_h-view_h));}
