static int ends_with(const char*path,const char*ext){unsigned i=0;while(path[i])i++;unsigned j=0;while(ext[j])j++;if(j>i)return 0;for(unsigned k=0;k<j;k++){char a=path[i-j+k],b=ext[k];if(a>='A'&&a<='Z')a=(char)(a+32);if(b>='A'&&b<='Z')b=(char)(b+32);if(a!=b)return 0;}return 1;}
static void put_le32(unsigned char*p,uint32_t n){p[0]=(unsigned char)n;p[1]=(unsigned char)(n>>8);p[2]=(unsigned char)(n>>16);p[3]=(unsigned char)(n>>24);}
static int save_bmp(const char*path){uint32_t stride=((PAINT_W*24u+31u)/32u)*4u,size=54u+stride*PAINT_H;if(size>BMP_CAP)return -1;for(unsigned i=0;i<size;i++)bmp_data[i]=0;bmp_data[0]='B';bmp_data[1]='M';put_le32(bmp_data+2,size);put_le32(bmp_data+10,54);put_le32(bmp_data+14,40);put_le32(bmp_data+18,PAINT_W);put_le32(bmp_data+22,PAINT_H);bmp_data[26]=1;bmp_data[28]=24;put_le32(bmp_data+34,stride*PAINT_H);for(int y=0;y<PAINT_H;y++)for(int x=0;x<PAINT_W;x++){uint32_t c=pixels[y*PAINT_W+x];unsigned char*q=bmp_data+54+(PAINT_H-1-y)*stride+x*3;q[0]=(unsigned char)c;q[1]=(unsigned char)(c>>8);q[2]=(unsigned char)(c>>16);}return dm_host_fs_write(path,(char*)bmp_data,(int32_t)size,0);}
static void save_to(const char*path){int result=ends_with(path,".bmp")?save_bmp(path):dm_host_image_save_png(path,PAINT_W,PAINT_H,pixels,0);if(result>=0){unsigned i=0;while(path[i]&&i<sizeof(saved_path)-1){saved_path[i]=path[i];i++;}saved_path[i]=0;dirty=0;status[0]=0;}else{const char*m="Salvataggio non riuscito";unsigned i=0;while(m[i]&&i<sizeof(status)-1){status[i]=m[i];i++;}status[i]=0;}}
static void save(void){if(saved_path[0])save_to(saved_path);else{save_pending=1;dm_host_file_dialog("Paint - Salva immagine",".png,.bmp",1,file_path,sizeof(file_path));}}
static void open_image(void){open_pending=1;dm_host_file_dialog("Paint - Apri immagine",".bmp,.png,.jpg,.jpeg",0,file_path,sizeof(file_path));}
static void clear_canvas(void){save_undo();for(int i=0;i<PAINT_PIXELS;i++)pixels[i]=background();saved_path[0]=0;dirty=1;changed();status[0]=0;selection_active=0;polygon_count=curve_stage=0;}
void dm_app_init(const char*argument){(void)argument;canvas_w=480;canvas_h=300;if(!ensure_buffers(PAINT_PIXELS)){set_status("Memoria insufficiente per Paint");return;}for(int i=0;i<PAINT_PIXELS;i++)pixels[i]=0xFFFFFFFFu;image=dm_host_image_create(PAINT_W,PAINT_H,pixels);tool=TOOL_PENCIL;brush_size=1;fill_style=0;zoom_percent=100;fit_mode=1;offset_x=offset_y=0;dirty=dragging=has_undo=eraser_mode=selection_active=polygon_count=curve_stage=fg_custom_active=0;canvas_resize_drag=resize_prompt=0;fg_index=0;bg_index=1;clipboard_w=clipboard_h=paste_mode=0;file_path[0]=saved_path[0]=input_text[0]=status[0]=0;}
void dm_app_file_result(uint32_t length){if(length>=sizeof(file_path))return;file_path[length]=0;if(open_pending){open_pending=0;if(ends_with(file_path,".bmp"))load_bmp(file_path);else load_raster(file_path);}else if(save_pending){save_pending=0;save_to(file_path);}}
static void canvas_point(int x,int y,int*cx,int*cy){*cx=clamp_i((x-canvas_x+offset_x)*PAINT_W/draw_w,0,PAINT_W-1);*cy=clamp_i((y-canvas_y+offset_y)*PAINT_H/draw_h,0,PAINT_H-1);}
static void render_preview(void){if(!dragging||tool==TOOL_PENCIL||tool==TOOL_BRUSH||tool==TOOL_ERASER||tool==TOOL_AIRBRUSH)return;int x0=canvas_x+start_x*draw_w/PAINT_W-offset_x,y0=canvas_y+start_y*draw_h/PAINT_H-offset_y,x1=canvas_x+last_x*draw_w/PAINT_W-offset_x,y1=canvas_y+last_y*draw_h/PAINT_H-offset_y;uint32_t c=0xFF202020u;if(tool==TOOL_LINE)draw_ui_line(x0,y0,x1,y1,c);else if(tool==TOOL_ELLIPSE){int l=min_i(x0,x1),r=max_i(x0,x1),t=min_i(y0,y1),b=max_i(y0,y1);for(int i=0;i<=24;i++){int px=l+(r-l)*i/24,py=t+(b-t)*i/24;draw_ui_line(px,t+(b-t)/2,px,py,c);}}else{draw_ui_line(x0,y0,x1,y0,c);draw_ui_line(x1,y0,x1,y1,c);draw_ui_line(x1,y1,x0,y1,c);draw_ui_line(x0,y1,x0,y0,c);}}
void dm_app_draw(int32_t width,int32_t height){layout(width,height);dm_host_rect(0,0,width,height,0xFFC6C6C6u);
 for(int i=0;i<TOOL_COUNT;i++)icon_draw(4+(i%2)*22,4+(i/2)*21,i);
 dm_host_rect(5,173,18,18,foreground());dmw_border((DmWidgetRect){5,173,18,18},0);dm_host_rect(17,182,18,18,background());dmw_border((DmWidgetRect){17,182,18,18},0);
 for(int i=0;i<PALETTE_COUNT;i++){int x=4+(i%4)*11,y=204+(i/4)*11;dm_host_rect(x,y,10,10,palette[i]);dmw_border((DmWidgetRect){x,y,10,10},0);if(i==fg_index)dm_host_rect(x+1,y+1,2,2,0xFFFFFFFFu);}
 dm_host_rect(canvas_x,canvas_y,view_w,view_h,0xFFC6C6C6u);if(image>0)dm_host_image_draw_clipped(image,canvas_x-offset_x,canvas_y-offset_y,draw_w,draw_h,canvas_x,canvas_y,view_w,view_h);render_preview();if(selection_active){int x0=canvas_x+selection_x0*draw_w/PAINT_W-offset_x,y0=canvas_y+selection_y0*draw_h/PAINT_H-offset_y,x1=canvas_x+selection_x1*draw_w/PAINT_W-offset_x,y1=canvas_y+selection_y1*draw_h/PAINT_H-offset_y;for(int x=x0;x<=x1;x+=4){dm_host_rect(x,y0,2,1,0xFF202020u);dm_host_rect(x,y1,2,1,0xFF202020u);}for(int y=y0;y<=y1;y+=4){dm_host_rect(x0,y,1,2,0xFF202020u);dm_host_rect(x1,y,1,2,0xFF202020u);}}
 if(!hbar&&!vbar&&draw_w<=view_w&&draw_h<=view_h){int gx=canvas_x+draw_w-8,gy=canvas_y+draw_h-8;dm_host_rect(gx,gy,8,8,0xFFC6C6C6u);dm_host_rect(gx+2,gy+5,5,1,0xFF777777u);dm_host_rect(gx+5,gy+2,1,4,0xFF777777u);}
 if(hbar)dm_host_scrollbar_draw(canvas_x,canvas_y+view_h+2,view_w,10,0,draw_w,view_w,offset_x);if(vbar)dm_host_scrollbar_draw(canvas_x+view_w+2,canvas_y,10,view_h,1,draw_h,view_h,offset_y);if(hbar&&vbar)dm_host_rect(canvas_x+view_w+2,canvas_y+view_h+2,10,10,0xFFC6C6C6u);
 dm_host_text(5,height-7,tool_names[tool],0xFF202020u);if(status[0])dm_host_text(150,height-7,status,0xFF8A2020u);else if(tool==TOOL_POLYGON&&polygon_count)dm_host_text(150,height-7,"Invio chiude il poligono",0xFF202020u);else if(tool==TOOL_CURVE&&curve_stage)dm_host_text(150,height-7,"Clicca il punto di controllo",0xFF202020u);}
static void choose_tool(int id){tool=clamp_i(id,0,TOOL_COUNT-1);polygon_count=curve_stage=0;eraser_mode=tool==TOOL_ERASER;}
static void undo_action(void){if(!has_undo)return;for(int i=0;i<PAINT_PIXELS;i++){uint32_t c=pixels[i];pixels[i]=undo[i];undo[i]=c;}dirty=1;changed();}
void dm_app_click(int32_t x,int32_t y,uint32_t buttons){if(!buttons)return;
 if(x>=4&&x<48&&y>=4&&y<172){int col=(x-4)/22,row=(y-4)/21,id=row*2+col;if(col<2&&row<8){choose_tool(id);return;}}
 if(x>=5&&x<35&&y>=173&&y<201){if(fg_custom_active){fg_custom=background();fg_custom_active=0;fg_index=bg_index;bg_index=1;}else{int t=fg_index;fg_index=bg_index;bg_index=t;}return;}
 if(x>=4&&x<48&&y>=204&&y<282){int col=(x-4)/11,row=(y-204)/11,index=row*4+col;if(index>=0&&index<PALETTE_COUNT){if(buttons&2)bg_index=index;else{fg_index=index;fg_custom_active=0;}eraser_mode=0;}return;}
 if(hbar&&dmw_scrollbar_click(horizontal_scroll_hit(),x,y,draw_w,view_w,&offset_x)){scroll_drag=1;return;}if(vbar&&dmw_scrollbar_click((DmWidgetRect){canvas_x+view_w+2,canvas_y,10,view_h},x,y,draw_h,view_h,&offset_y)){scroll_drag=2;return;}
 if(!hbar&&!vbar&&draw_w<=view_w&&draw_h<=view_h&&x>=canvas_x+draw_w-10&&x<canvas_x+draw_w&&y>=canvas_y+draw_h-10&&y<canvas_y+draw_h){canvas_resize_drag=1;resize_start_w=PAINT_W;resize_start_h=PAINT_H;resize_start_draw_w=draw_w;resize_start_draw_h=draw_h;return;}
 if(x<canvas_x||x>=canvas_x+view_w||y<canvas_y||y>=canvas_y+view_h)return;int cx,cy;canvas_point(x,y,&cx,&cy);if(paste_mode){paste_at(cx,cy);return;}
 if(tool==TOOL_ZOOM){fit_mode=0;zoom_percent=zoom_percent>=400?50:zoom_percent*2;offset_x=offset_y=0;return;}if(tool==TOOL_PICKER){fg_custom=pixels[cy*PAINT_W+cx];fg_custom_active=1;return;}if(tool==TOOL_FILL){save_undo();fill_area(cx,cy);return;}if(tool==TOOL_TEXT){text_x=cx;text_y=cy;dm_host_text_prompt("Paint - inserisci testo","",input_text,sizeof(input_text));return;}
 if(tool==TOOL_POLYGON){if(polygon_count==0)save_undo();if(polygon_count<POINT_LIMIT){polygon_x[polygon_count]=cx;polygon_y[polygon_count++]=cy;}return;}if(tool==TOOL_CURVE){if(curve_stage==0){save_undo();curve_x[0]=cx;curve_y[0]=cy;curve_stage=1;}else if(curve_stage==1){curve_x[2]=cx;curve_y[2]=cy;curve_stage=2;}else{curve_x[1]=cx;curve_y[1]=cy;int px=curve_x[0],py=curve_y[0];for(int t=1;t<=40;t++){int u=40-t,nx=(u*u*curve_x[0]+2*u*t*curve_x[1]+t*t*curve_x[2])/1600,ny=(u*u*curve_y[0]+2*u*t*curve_y[1]+t*t*curve_y[2])/1600;line_pixels(px,py,nx,ny);px=nx;py=ny;}curve_stage=0;changed();}return;}
 save_undo();canvas_point(x,y,&start_x,&start_y);last_x=start_x;last_y=start_y;dragging=1;if(tool==TOOL_PENCIL||tool==TOOL_BRUSH||tool==TOOL_ERASER){dot(start_x,start_y);changed();}else if(tool==TOOL_AIRBRUSH){draw_airbrush(start_x,start_y);changed();}}
void dm_app_tick(uint32_t ms){(void)ms;int32_t x=0,y=0,held=0,focused=dm_host_pointer_state(&x,&y,&held);if(canvas_resize_drag){if(focused&&held)return;canvas_resize_drag=0;int nw=resize_start_w+(x-(canvas_x+resize_start_draw_w))*resize_start_w/max_i(1,resize_start_draw_w);int nh=resize_start_h+(y-(canvas_y+resize_start_draw_h))*resize_start_h/max_i(1,resize_start_draw_h);resize_canvas(clamp_i(nw,1,MAX_PAINT_W),clamp_i(nh,1,MAX_PAINT_H));return;}if(scroll_drag){if(!focused||!held)scroll_drag=0;else if(scroll_drag==1)dmw_scrollbar_click(horizontal_scroll_hit(),x,y,draw_w,view_w,&offset_x);else dmw_scrollbar_click((DmWidgetRect){canvas_x+view_w+2,canvas_y,10,view_h},x,y,draw_h,view_h,&offset_y);return;}if(!dragging)return;if(focused&&held&&x>=canvas_x&&x<canvas_x+view_w&&y>=canvas_y&&y<canvas_y+view_h){canvas_point(x,y,&last_x,&last_y);if(tool==TOOL_PENCIL||tool==TOOL_BRUSH||tool==TOOL_ERASER)line_pixels(start_x,start_y,last_x,last_y),start_x=last_x,start_y=last_y;else if(tool==TOOL_AIRBRUSH)draw_airbrush(last_x,last_y);if(tool==TOOL_PENCIL||tool==TOOL_BRUSH||tool==TOOL_ERASER||tool==TOOL_AIRBRUSH)changed();}else if(!focused||!held){if(tool==TOOL_RECT_SELECT||tool==TOOL_FREE_SELECT){selection_active=1;selection_x0=min_i(start_x,last_x);selection_y0=min_i(start_y,last_y);selection_x1=max_i(start_x,last_x);selection_y1=max_i(start_y,last_y);}else apply_shape();dragging=0;}}
void dm_app_text(uint32_t n){if(n>=sizeof(input_text))n=sizeof(input_text)-1;input_text[n]=0;if(resize_prompt){int w=0,h=0;char*p=input_text;while(*p>='0'&&*p<='9'){if(w<=MAX_PAINT_W)w=w*10+(*p-'0');p++;}if(*p=='x'||*p=='X'||*p==',')p++;while(*p>='0'&&*p<='9'){if(h<=MAX_PAINT_H)h=h*10+(*p-'0');p++;}if(w>0&&h>0&&w<=MAX_PAINT_W&&h<=MAX_PAINT_H){if(resize_canvas(w,h))set_status("Dimensione tela aggiornata");}else set_status("Usa larghezza x altezza (max 1024 x 768)");resize_prompt=0;return;}if(tool==TOOL_TEXT){save_undo();draw_text_pixels(text_x,text_y,input_text);}}
void dm_app_key(int32_t key){if(key==DM_WASM_KEY_SAVE)save();else if(key==DM_WASM_KEY_COPY)selection_copy(0);else if(key==DM_WASM_KEY_CUT)selection_copy(1);else if(key==DM_WASM_KEY_PASTE&&clipboard_w)paste_mode=1;else if(key==DM_WASM_KEY_SELECT_ALL){selection_active=1;selection_x0=selection_y0=0;selection_x1=PAINT_W-1;selection_y1=PAINT_H-1;}else if(key==DM_WASM_KEY_ENTER&&tool==TOOL_POLYGON)draw_polygon();else if(key==DM_WASM_KEY_ENTER&&tool==TOOL_CURVE)curve_stage=0;else if(key==DM_WASM_KEY_LEFT)offset_x=clamp_i(offset_x-24,0,max_i(0,draw_w-view_w));else if(key==DM_WASM_KEY_RIGHT)offset_x=clamp_i(offset_x+24,0,max_i(0,draw_w-view_w));else if(key==DM_WASM_KEY_UP)offset_y=clamp_i(offset_y-24,0,max_i(0,draw_h-view_h));else if(key==DM_WASM_KEY_DOWN)offset_y=clamp_i(offset_y+24,0,max_i(0,draw_h-view_h));else if(key==DM_WASM_KEY_DELETE)clear_canvas();}
void dm_app_menu(int32_t command){if(command==DM_WASM_MENU_NEW)clear_canvas();else if(command==DM_WASM_MENU_OPEN)open_image();else if(command==DM_WASM_MENU_SAVE)save();else if(command==DM_WASM_MENU_SAVE_AS){save_pending=1;dm_host_file_dialog("Paint - Salva immagine",".png,.bmp",1,file_path,sizeof(file_path));}else if(command==DM_WASM_MENU_UNDO)undo_action();else if(command==DM_WASM_MENU_CUT)dm_app_key(DM_WASM_KEY_CUT);else if(command==DM_WASM_MENU_COPY)dm_app_key(DM_WASM_KEY_COPY);else if(command==DM_WASM_MENU_PASTE)dm_app_key(DM_WASM_KEY_PASTE);else if(command==DM_WASM_MENU_SELECT_ALL)dm_app_key(DM_WASM_KEY_SELECT_ALL);else if(command==DM_WASM_MENU_ZOOM_IN){fit_mode=0;zoom_percent=clamp_i(zoom_percent*2,50,400);}else if(command==DM_WASM_MENU_ZOOM_OUT){fit_mode=0;zoom_percent=clamp_i(zoom_percent/2,50,400);}else if(command==DM_WASM_MENU_IMAGE_SIZE){resize_prompt=1;int n=0,w=PAINT_W,h=PAINT_H;char rev[12];do{rev[n++]=(char)('0'+w%10);w/=10;}while(w&&n<10);for(int i=0;i<n;i++)input_text[i]=rev[n-i-1];input_text[n++]='x';int m=0;do{rev[m++]=(char)('0'+h%10);h/=10;}while(h&&m<10);for(int i=0;i<m;i++)input_text[n++]=rev[m-i-1];input_text[n]=0;dm_host_text_prompt("Paint - Attributi immagine",input_text,input_text,sizeof(input_text));}else if(command==DM_WASM_MENU_CLEAR)clear_canvas();}
uint32_t dm_app_dirty(void){return dirty!=0;}
void dm_app_discard(void){dirty=0;}
void dm_app_close(void){if(image>0)dm_host_image_free(image);image=0;}
